custom-reduced-motion.code:
/*
 * Respect the OS "reduce motion" setting: when a user has asked for less
 * animation, collapse every transition/animation to an instant change
 * (including the library's slide/fade-in utilities) and stop smooth scrolling.
 */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

index-arms-colours.code:
/*
 * ARMS-derived colours. Mixed from the library's tokens, so they follow the
 * light/dark toggle on their own — reach for these instead of hex values
 * when a page needs a shade the library doesn't name.
 *   --heading-accent  navy heading text (a lighter blue in dark mode)
 *   --primary-hover   pressed/hovered primary buttons
 *   --brand-overlay   navy wash over photos behind white text
 *   --status-*        timetable status colours (badge dots, the dashboard's
 *                     status bar). Red is kept out of these on purpose: red
 *                     means "has clashes" (--status-clash), and an inactive
 *                     timetable isn't an error.
 */
:root {
  --heading-accent: color-mix(in oklab, var(--primary) 60%, var(--foreground));
  --primary-hover: color-mix(in oklab, var(--primary) 85%, black);
  --brand-overlay: color-mix(in oklab, var(--sidebar) 75%, transparent);
  --status-published: var(--success);
  --status-pending: var(--warning);
  --status-inactive: color-mix(in oklab, var(--muted-foreground) 55%, transparent);
  --status-clash: var(--destructive);
}

typography-scale.code:
:root {
  /* Type scale — one place to tune every heading/subheading/body size. */
  --text-page-title: 1.5rem; /* page-level h1, e.g. "Settings" */
  --text-section-title: 1.25rem; /* h2 section headings within a page */
  --text-card-title: 1.125rem; /* card/collapsible-card titles */
  --text-card-subtitle: 0.875rem; /* card/collapsible-card descriptions */
  --text-body: 0.875rem; /* default body/paragraph text */
  --text-label: 0.75rem; /* field labels, eyebrow text, meta text */
}

.page-title {
  font-family: var(--font-serif, "Trebuchet MS", Trebuchet, "Segoe UI", Verdana, sans-serif);
  font-size: var(--text-page-title);
  font-weight: 700;
  line-height: 1.25;
  color: var(--foreground);
  /* Padding between the page heading and the content below it. */
  margin-bottom: var(--space-6);
}

