index-dark-variant.code:
/*
 * tut-components-library's compiled CSS defines its dark palette under a
 * literal `.dark{...}` class selector (see dist/styles.css) — a class you
 * toggle, not `prefers-color-scheme`. Tailwind v4's `dark:` variant defaults
 * to a `prefers-color-scheme` media query unless told otherwise, which would
 * silently ignore the `.dark` class ThemeContext toggles on <html>. This
 * repoints `dark:` at that same class so ARMS's own `dark:` utilities
 * (e.g. `dark:bg-sidebar`) react to the same toggle as the library's tokens.
 */
@custom-variant dark (&:where(.dark, .dark *));

theme-apply.code:
export const FAVICON_LIGHT = '/TUT Web Icon.png'
export const FAVICON_DARK = '/TUT White Logo.png'

/** Swaps the favicon to the white TUT logo in dark mode, the color logo otherwise. */
export function applyFavicon(isDark) {
  if (typeof document === 'undefined') return
  const link = document.getElementById('favicon')
  if (link) link.href = isDark ? FAVICON_DARK : FAVICON_LIGHT
}

/** Toggles the `dark` class on `<html>` to match the given theme preference. */
export function applyTheme(theme) {
  if (typeof document === 'undefined') return
  const isDark = resolveIsDark(theme)
  document.documentElement.classList.toggle('dark', isDark)
  applyFavicon(isDark)
}

index-html-anti-flash.code:
(function () {
  try {
    var storedTheme = localStorage.getItem('arms_theme') || 'light'
    var isDark =
      storedTheme === 'dark' ||
      (storedTheme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)

    if (isDark) {
      document.documentElement.classList.add('dark')
      document.getElementById('favicon').href = '/TUT White Logo.png'
    } else {
      document.documentElement.classList.remove('dark')
      document.getElementById('favicon').href = '/TUT Web Icon.png'
    }
  } catch (e) {
    // localStorage/matchMedia unavailable — fall back to light mode.
  }
})()

