be-host-resilience.code:
// =====================================================
// HOST RESILIENCE
// =====================================================
//
// By default, an unhandled exception in ANY IHostedService/
// BackgroundService (e.g. AcademicCalendarNotificationBackgroundService)
// stops the entire host - a bug in one background job takes the whole
// API down. Ignore instead: the offending service stops, everything
// else (including the API itself) keeps running, and the exception is
// still logged by the framework.
//

builder.Services.Configure<Microsoft.Extensions.Hosting.HostOptions>(
    options =>
    {
        options.BackgroundServiceExceptionBehavior =
            Microsoft.Extensions.Hosting.BackgroundServiceExceptionBehavior.Ignore;
    });

