be-token-life.code:
// A token lives for the idle limit only. Each sign-in and each
// POST api/auth/keep-alive (sent by the frontend while the user is
// active) issues a fresh one, so an active session keeps going while a
// session left alone for the idle limit stops working on the server too
// - not just in the browser.
public int SessionTimeoutMinutes =>
    int.TryParse(
        _configuration["Session:IdleTimeoutMinutes"],
        out int minutes) && minutes > 0
            ? minutes
            : DefaultSessionTimeoutMinutes;

public int TokenLifetimeMinutes =>
    SessionTimeoutMinutes + TokenGraceMinutes;

