be-verify-find.code:
var otpRecord = await _context.Otps
    .Where(o =>
        o.email == email &&
        !o.is_used)
    .OrderByDescending(o => o.created_at)
    .FirstOrDefaultAsync();

if (otpRecord == null)
{
    return Unauthorized(new
    {
        message = "Invalid or expired OTP."
    });
}

// =====================================================
// CHECK EXPIRATION
// =====================================================

// identity_db.otp stores created_at/expires_at as
// "timestamp without time zone", and the database session time zone
// is Africa/Johannesburg - so the UTC expiry written at login is saved
// as local (UTC+2) wall-clock time. Comparing that value in C# with
// DateTime.UtcNow made every OTP stay valid for ~2h05m instead of
// 5 minutes. Compare inside the database instead, where now() and the
// stored value are interpreted in the same session time zone.
var hasExpired = await _context.Otps
    .Where(o => o.otp_id == otpRecord.otp_id)
    .Select(o => o.expires_at < DateTime.UtcNow)
    .FirstAsync();

if (hasExpired)
{
    otpRecord.is_used = true;

    await _context.SaveChangesAsync();

    return Unauthorized(new
    {
        message =
            "OTP has expired. Please request a new OTP."
    });
}

