be-keepalive.code:
[Authorize]
[HttpPost("keep-alive")]
public async Task<IActionResult> KeepAlive()
{
    var userIdValue = User.FindFirst(ClaimTypes.NameIdentifier)?.Value;

    if (!int.TryParse(userIdValue, out var userId))
    {
        return Unauthorized(new
        {
            message = "Invalid session."
        });
    }

    var user = await _context.Users
        .Include(u => u.Role)
        .FirstOrDefaultAsync(u => u.user_id == userId);

    if (user == null)
    {
        return Unauthorized(new
        {
            message = "Account not found."
        });
    }

    var sessionMinutes = _tokenService.SessionTimeoutMinutes;

    return Ok(new
    {
        message = "Session extended.",
        token = _tokenService.GenerateToken(user),
        expiresAtUtc = DateTime.UtcNow.AddMinutes(_tokenService.TokenLifetimeMinutes),
        sessionTimeoutMinutes = sessionMinutes
    });
}

be-hasher.code:
public bool VerifyPassword(
    string password,
    string passwordHash)
{
    if (string.IsNullOrWhiteSpace(password))
        return false;

    if (string.IsNullOrWhiteSpace(passwordHash))
        return false;

    // Detect legacy plaintext passwords stored directly in the
    // database (pre-seeded accounts). If the stored value is not
    // a BCrypt hash, fall back to a plaintext comparison.
    if (!IsBcryptHash(passwordHash))
    {
        return password == passwordHash;
    }

    return BCrypt.Net.BCrypt.Verify(
        password,
        passwordHash);
}

private static bool IsBcryptHash(string value)
{
    // BCrypt hashes look like: $2a$10$..., $2b$..., $2y$...
    // with a version, cost, and 22-char salt + 31-char hash.
    return value.Length >= 60
        && value[0] == '$'
        && (value.StartsWith("$2a$")
            || value.StartsWith("$2b$")
            || value.StartsWith("$2y$")
            || value.StartsWith("$2x$"));
}

be-password-rules.code:
private static void ValidatePassword(string password)
{
    if (string.IsNullOrWhiteSpace(password))
    {
        throw new ArgumentException(
            "Password is required.");
    }

    // Maximum 13 characters
    if (password.Length > 13)
    {
        throw new ArgumentException(
            "Password must not exceed 13 characters.");
    }

    // Minimum 6 characters
    if (password.Length < 6)
    {
        throw new ArgumentException(
            "Password must be at least 6 characters.");
    }

    bool hasLetter =
        password.Any(char.IsLetter);

    bool hasNumber =
        password.Any(char.IsDigit);

    bool hasSpecial =
        password.Any(
            c => !char.IsLetterOrDigit(c));

    if (!hasLetter)
    {
        throw new ArgumentException(
            "Password must contain at least one alphabet letter.");
    }

    if (!hasNumber)
    {
        throw new ArgumentException(
            "Password must contain at least one number.");
    }

    if (!hasSpecial)
    {
        throw new ArgumentException(
            "Password must contain at least one special character.");
    }
}

