    public static BaseResponse<T> Success(T data) => new()
    {
        IsSuccess = true,
        Data = data
    };

    public static BaseResponse<T> Failure(params string[] errors) => new()
    {
        IsSuccess = false,
        Errors = errors
    };

    public static BaseResponse<T> ValidationFailure(IEnumerable<string> errors) => new()
    {
        IsSuccess = false,
        Errors = errors.ToList().AsReadOnly()
    };
}

