private async Task SendAsync(
    string email,
    string subject,
    string body,
    bool throwOnFailure,
    bool isHtml = false)
{
    if (string.IsNullOrWhiteSpace(email))
    {
        return;
    }

    // appsettings.json ships these as "" (not null), so a plain ??
    // would never reach the environment-variable fallback.
    var scriptUrl = NullIfBlank(_configuration["EmailSettings:MailScriptUrl"])
        ?? NullIfBlank(Environment.GetEnvironmentVariable("MAIL_SCRIPT_URL"));

    var secret = NullIfBlank(_configuration["EmailSettings:MailSecret"])
        ?? NullIfBlank(Environment.GetEnvironmentVariable("MAIL_SECRET"));

    if (scriptUrl == null || secret == null)
    {
        var problem =
            "Email is not configured (EmailSettings:MailScriptUrl / MailSecret, " +
            "or MAIL_SCRIPT_URL / MAIL_SECRET).";

        _logger.LogWarning("{Problem} Skipped email to {Email}.", problem, email);

        if (throwOnFailure)
        {
            throw new InvalidOperationException(problem);
        }

        return;
    }

    try
    {
        // The script sends HTML; plain-text bodies are encoded so
        // line breaks and special characters survive.
        var html = isHtml
            ? body
            : WebUtility.HtmlEncode(body).Replace("\n", "<br>");

        var payload = new { secret, to = email, subject, html };

        using var content = new StringContent(
            JsonSerializer.Serialize(payload),
            Encoding.UTF8,
            "application/json");

        using var response = await _httpClient.PostAsync(scriptUrl, content);

        string responseBody;

        if (response.StatusCode is HttpStatusCode.Found
                or HttpStatusCode.SeeOther
                or HttpStatusCode.MovedPermanently
                or HttpStatusCode.TemporaryRedirect
            && response.Headers.Location != null)
        {
            // doPost() has run; now fetch what it returned.
            var fetched = await TryFetchScriptResultAsync(
                new Uri(new Uri(scriptUrl), response.Headers.Location));

            if (fetched == null)
            {
                _logger.LogWarning(
                    "Mail script ran for {Email} but its result could not be fetched " +
                    "(Google's result page failed); treating the email as sent.",
                    email);

                return;

