protected override async Task ExecuteAsync(CancellationToken stoppingToken)
{
    if (!_enabled)
    {
        _logger.LogInformation("Admin request reminders are switched off (AdminRequestReminders:Enabled = false).");
        return;
    }

    try
    {
        await Task.Delay(_startupDelay, stoppingToken);
    }
    catch (OperationCanceledException)
    {
        return;
    }

    using var timer = new PeriodicTimer(_interval);

    do
    {
        try
        {
            using var scope = _services.CreateScope();
            var reminders = scope.ServiceProvider.GetRequiredService<AdminRequestReminderService>();
            var result = await reminders.RunAsync(stoppingToken);

            if (result.LapsedBookingRequests > 0 || result.Title != null)
            {
                _logger.LogInformation(
                    "Admin request reminders: {Lapsed} lapsed, {Bookings} booking and {Access} lab access request(s) reminded to {Admins} admin(s).",
                    result.LapsedBookingRequests, result.BookingRequestsReminded, result.LabAccessRequestsReminded, result.AdminsNotified);
            }
        }
        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
        {
            return;
        }
        catch (Exception ex)
        {
            // Never let a failed run stop the service; try again next tick.
            _logger.LogError(ex, "The admin request reminder run failed.");
        }
    }
    while (await WaitAsync(timer, stoppingToken));
}

be-bg-calendar.code:
protected override async Task ExecuteAsync(
    CancellationToken stoppingToken)
{
    _logger.LogInformation(
        "Academic calendar notification background service started. " +
        "Startup check in {Delay}s, then daily at {Hours} UTC.",
        _startupDelaySeconds,
        string.Join(", ", _notificationHours));

    try
    {
        // ---------------------------------------------------------
        // INITIAL STARTUP DELAY
        // ---------------------------------------------------------

        if (_startupDelaySeconds > 0)
        {
            await Task.Delay(
                TimeSpan.FromSeconds(_startupDelaySeconds),
                stoppingToken);
        }

        if (stoppingToken.IsCancellationRequested)
            return;

        // ---------------------------------------------------------
        // STARTUP CHECK
        // ---------------------------------------------------------
        // Clear today's reminders first so the corrected
        // 30/14/7/1/0-day interval logic can be delivered again.

        await RunCheckAsync(
            stoppingToken,
            clearToday: true);
    }
    catch (OperationCanceledException)
        when (stoppingToken.IsCancellationRequested)
    {
        return;
    }

    // -------------------------------------------------------------
    // DAILY SCHEDULED CHECKS
    // -------------------------------------------------------------

    while (!stoppingToken.IsCancellationRequested)
    {
        var delay = GetDelayUntilNextRun();

        _logger.LogDebug(
            "Next academic calendar notification check in " +
            "{Minutes:F1} minutes.",
            delay.TotalMinutes);

        try
        {
            await Task.Delay(
                delay,
                stoppingToken);
        }
        catch (OperationCanceledException)
            when (stoppingToken.IsCancellationRequested)
        {
            break;
        }

        if (stoppingToken.IsCancellationRequested)
            break;

        await RunCheckAsync(
            stoppingToken,
            clearToday: false);
    }

    _logger.LogInformation(
        "Academic calendar notification background service stopped.");
}

