[HttpPut("user/{userId:int}/credentials")]
[Authorize(Roles = "SystemAdmin")]
public async Task<IActionResult> UpdateLecturerCredentials(
    int userId,
    [FromBody] UpdateLecturerCredentialsDto request)
{
    if (request == null ||
        (string.IsNullOrWhiteSpace(request.Email) &&
         string.IsNullOrWhiteSpace(request.NewPassword)))
    {
        return BadRequest(new
        {
            message = "Provide an email and/or a newPassword."
        });
    }

    var lecturer = await _context.Lecturers
        .Include(l => l.User)
        .FirstOrDefaultAsync(l => l.user_id == userId);

    if (lecturer?.User == null)
    {
        return NotFound(new
        {
            message = "Lecturer record not found."
        });
    }

    if (!string.IsNullOrWhiteSpace(request.Email))
    {
        var email = request.Email.Trim();

        // Lecturers may sign in with either an official TUT staff
        // address or a personal Gmail address - see AuthController's
        // LecturerLogin for the matching rule.
        var staffDomain =
            _configuration["Authentication:StaffEmailDomain"]
            ?? "@tut.ac.za";

        var lecturerGmailDomain =
            _configuration["Authentication:LecturerGmailDomain"]
            ?? "@gmail.com";

        var validDomain =
            email.EndsWith(staffDomain, StringComparison.OrdinalIgnoreCase) ||
            email.EndsWith(lecturerGmailDomain, StringComparison.OrdinalIgnoreCase);

        if (!validDomain)
        {
            return BadRequest(new
            {
                message =
                    $"Lecturer email must end with {staffDomain} or {lecturerGmailDomain}."
            });
        }

        var emailTaken = await _context.Users.AnyAsync(
            u => u.user_id != userId &&
                 u.email.ToLower() == email.ToLower());

        if (emailTaken)
        {
            return Conflict(new
            {
                message = "That email is already in use by another account."
            });
        }

        lecturer.User.email = email;
    }

    if (!string.IsNullOrWhiteSpace(request.NewPassword))
    {
        try
        {
            lecturer.User.password_hash =
                _passwordHasher.HashPassword(request.NewPassword);
        }
        catch (ArgumentException ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    await _context.SaveChangesAsync();

    return Ok(new
    {
        message = "Lecturer credentials updated successfully.",
        lecturer.user_id,
        email = lecturer.User.email
    });
}

