        entry =>
        {
            CacheRegions.AcademicData.Apply(
                entry,
                TimeSpan.FromHours(1));

            return ResolveFacultyAsync(userId, role);
        });

    if (faculty == null)
    {
        return NotFound(new
        {
            message = notFoundMessage
        });
