[HttpPut("{id:int}/publish")]
public async Task<IActionResult> Publish(int id)
{
    var timetable = await _context.ManagedTimetables
        .FirstOrDefaultAsync(m => m.managed_timetable_id == id);

    if (timetable == null)
    {
        return NotFound(new
        {
            message = "Timetable not found."
        });
    }

    // The timetable(s) live for this type + faculty until now - what the
    // change alerts compare the newly published one against.
    var previousTimetableIds = await _context.ManagedTimetables
        .Where(m =>
            m.type == timetable.type &&
            m.faculty_id == timetable.faculty_id &&
            m.status == "Published" &&
            m.managed_timetable_id != timetable.managed_timetable_id)
        .Select(m => m.managed_timetable_id)
        .ToListAsync();

    await DeactivateOtherPublishedAsync(timetable);

    timetable.status = "Published";
    timetable.updated_at = DateTime.UtcNow;

    await _context.SaveChangesAsync();

    QueueChangeAlerts(
        timetable.managed_timetable_id,
        previousTimetableIds,
        timetable.type);

    try
    {
        await _notifications.NotifyRoleAsync(
            NotificationType.Admin,
            $"{timetable.name} published",
            $"{timetable.name} has been published. Check your timetable for the update.",
            UserRole.Lecturer);
    }
    catch (Exception)
    {
        // Never let a notification failure undo the publish.
    }

    return Ok(new
    {
        message = "Timetable published.",
        timetable.managed_timetable_id,
        timetable.status
    });
}

