            m.faculty_id == timetable.faculty_id &&
            m.status == "Published" &&
            m.managed_timetable_id != timetable.managed_timetable_id)
        .ExecuteUpdateAsync(s => s
            .SetProperty(m => m.status, "Inactive")
            .SetProperty(m => m.updated_at, DateTime.UtcNow));
}

