// ============================================================
// CLASS TIMETABLE CLASHES  (admin check before publishing)
// ============================================================
//
// A clash is a student who would see two different modules in
// overlapping times on the same day. Works on any managed class
// timetable (normally a Pending one) and resolves each student's
// sessions the same way their own timetable does: enrolled modules,
// their allocated group, and the same semester filter. A module the
// student has no group for yet counts only when it has a single
// group (the one they'd be given); otherwise it is reported under
// UnallocatedStudents instead of guessed. Back-to-back sessions
// (one ends as the next starts) don't clash.
// ============================================================

public sealed record ClashSession(
    string ModuleCode,
    string ModuleName,
    string Group,
    string Venue,
    string Time);

public sealed record ClassClash(
    string Day,
    string Time,
    List<ClashSession> Sessions,
    bool SameSemester,
    int StudentCount,
    List<string> Students);

public sealed record ClassClashReport(
    int StudentsChecked,
    int StudentsWithClashes,
    int UnallocatedStudents,
    List<ClassClash> Clashes);

