foreach (var session in ordered)
{
    if (blocks.Count == 0 || session.Start >= blockEnd)
    {
        blocks.Add(new() { session });
        blockEnd = session.End;
    }
    else
    {
        blocks[^1].Add(session);

        if (session.End > blockEnd)
        {
            blockEnd = session.End;
        }
    }
}

foreach (var block in blocks)
{
    // The same module twice (e.g. a session in two venues)
    // is not a clash - it takes two different modules.
    if (block.Select(s => CodeOf(s.ModuleId))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Count() < 2)
    {
        continue;
    }

    hasClash = true;

    var blockModuleIds = block
        .Select(s => s.ModuleId)
        .Distinct()
        .ToList();

    var sameSemester = blockModuleIds
        .SelectMany((moduleId, index) =>
            blockModuleIds.Skip(index + 1)
                .Select(otherModuleId => (moduleId, otherModuleId)))
        .Any(pair =>
            enrolledSemestersByModule[pair.moduleId]
                .Overlaps(enrolledSemestersByModule[pair.otherModuleId]));

