    IFormFile file)
{
    if (file == null || file.Length == 0)
    {
        return BadRequest(new
        {
            message = "The uploaded file is empty."
        });
    }

    // Calendar events are read with ClosedXML, which can't open .xls.
    if (!string.Equals(
            Path.GetExtension(file.FileName),
            ".xlsx",
            StringComparison.OrdinalIgnoreCase))
    {
        return BadRequest(new
        {
            message = "Only Excel files (.xlsx) are allowed."
        });
    }

    try
    {
        // ----------------------------------------------------
        // GET LOGGED-IN ADMIN USER ID
        // ----------------------------------------------------

        var userIdClaim =
            User.FindFirst(
                ClaimTypes.NameIdentifier)?.Value
            ?? User.FindFirst("sub")?.Value;

        if (!int.TryParse(
                userIdClaim,
                out var userId))
        {
            return Unauthorized(new
            {
                message =
                    "Invalid user identity."
            });
        }

        // ----------------------------------------------------
        // UPLOAD
        // ----------------------------------------------------

        var previousPlanner =
            await _plannerService.GetLatestPlannerAsync();

        var planner =
            await _plannerService
                .UploadPlannerAsync(
                    file,
                    userId);

        // ----------------------------------------------------
        // IMPORT CALENDAR EVENTS FROM THE UPLOADED EXCEL FILE
        // ----------------------------------------------------

        int importedCount;

        try
        {
            importedCount =
                await _calendarImportService
                    .ImportAcademicCalendarAsync(
                        planner.planner_id,
                        planner.file_path);
        }
        catch
        {
            // The import failed and kept the previous events, so
            // the previous planner must stay the current one too.
            await _plannerService.DiscardFailedUploadAsync(
                planner.planner_id,
                previousPlanner?.planner_id);

            throw;
