public async Task<LabBookingDetailsDto> BookLabClassAsync(BookLabClassRequest request, int userId, string role)
{
    if (request == null)
        throw new ArgumentException("A booking request body is required.");

    var bookingRole = await RequireBookingRoleAsync(userId, role);

    if (request.LabId <= 0)
        throw new ArgumentException("lab_id is required: pick the lab or class to book.");

    // "Has internet" is a lecturer-only option.
    var isLecturer = bookingRole == LabBookingRole.Lecturer;
    if (!isLecturer && request.HasInternet.HasValue)
    {
        throw new UnauthorizedAccessException(
            "has_internet can only be set by lecturers. Leave it out of the request.");
    }

    // Open lab sessions are for lecturers, tutors and mentors; a student
    // booking through lab access books for themselves.
    if (bookingRole == LabBookingRole.Student && request.IsOpenLab)
    {
        throw new UnauthorizedAccessException(
            "Only lecturers, tutors and mentors can open a session to every student.");
    }

    var purpose = (request.Purpose ?? string.Empty).Trim();
    if (purpose.Length == 0)
        throw new ArgumentException("purpose is required, e.g. \"DPMC20 practical, group C\".");
    if (purpose.Length > PurposeMaxLength)
        throw new ArgumentException($"purpose must not exceed {PurposeMaxLength} characters.");

    if (request.ModuleId.HasValue &&
        !await _accessService.ModuleExistsAsync(request.ModuleId.Value))
    {
        throw new ArgumentException("The selected module does not exist in ARMS.");
    }

    var lab = await LoadActiveLabAsync(request.LabId);

    var (startUtc, endUtc) = await ValidateSelectionAsync(
        lab, userId, request.BookingDate, request.StartTime, request.EndTime, excludeBookingId: null);

be-book-save.code:
    // Booking rules: bookings held at once (requests + confirmed, not finished).
    var limits = await LimitsForAsync(userId);
    if (limits.Active is int maxActive)
    {
        var nowUtc = DateTime.UtcNow;
        var held = await _context.LabBookings.AsNoTracking()
            .CountAsync(b => b.booked_by_user_id == userId &&
                             LabBookingStatus.Active.Contains(b.status) &&
                             b.end_at > nowUtc);
        if (held >= maxActive)
        {
            throw new InvalidOperationException(
                $"You can have at most {Plural(maxActive, "booking")} at a time (requests and confirmed bookings), and you have {held}. " +
                "Cancel one, or book again once one has finished.");
        }
    }

    // Working hours (08:00-16:59) wait for a System Admin; after hours
    // (17:00-07:59) are confirmed by the system straight away.
    var needsApproval = NeedsApproval(startUtc, endUtc);

    var booking = new LabBooking
    {
        public_id = Guid.NewGuid(),
        lab_id = lab.lab_id,
        booked_by_user_id = userId,
        module_id = request.ModuleId,
        purpose = purpose,
        start_at = startUtc,
        end_at = endUtc,
        status = needsApproval ? LabBookingStatus.Pending : LabBookingStatus.Approved,
        created_at = DateTime.UtcNow,
        reviewed_at = needsApproval ? null : DateTime.UtcNow,
        booking_type = request.IsOpenLab ? LabBookingType.OpenLab : LabBookingType.Other,
        // Tutors/mentors keep the column default (true).
        has_internet = !isLecturer || (request.HasInternet ?? true)
    };

    _context.LabBookings.Add(booking);
    await SaveBookingChangesAsync();

    var details = (await BuildDetailsListAsync(new List<LabBooking> { booking }, bookingRole))[0];

    if (needsApproval)
        await _notifier.NotifyRequestReceivedAsync(details);
    else
        await _notifier.NotifyConfirmedAsync(details);

    await _activity.LogAsync(userId, VenueActivityCategory.Bookings,
        needsApproval
            ? (details.IsOpenLab ? "Requested an open lab" : "Requested a booking")
            : (details.IsOpenLab ? "Booked an open lab" : "Made a booking"),
        $"{details.Title} · {details.BookingReference}", details.LabId,
        new[]
        {
            $"{details.Date}, {details.StartTime}–{details.EndTime}.",
            $"Purpose: {details.Purpose}",
            needsApproval ? "Waiting for a System Admin to approve it." : "Confirmed automatically (after-hours booking)."
        });

    return details;
}

be-needs-approval.code:
private const int ReviewFromMinute = 8 * 60;   // 08:00 - working hours start
private const int ReviewUntilMinute = 17 * 60; // 17:00 - after hours start (16:59 is the last working minute)

/// <summary>True when a booking for [start, end) (UTC) needs a System Admin's approval: it overlaps 08:00-16:59 SAST.</summary>
private static bool NeedsApproval(DateTime startUtc, DateTime endUtc)
{
    var start = ToLocal(startUtc);
    var end = ToLocal(endUtc);

    for (var day = start.Date; day <= end.Date; day = day.AddDays(1))
    {
        var workStart = day.AddMinutes(ReviewFromMinute);
        var workEnd = day.AddMinutes(ReviewUntilMinute);
        if (start < workEnd && end > workStart)
            return true;
    }

    return false;
}

