namespace ARMS.Domain.Entities;

/// <summary>
/// lab_booking_db.lab_bookings — one booking of a lab or class venue.
///
/// Columns (see the live schema):
///   booking_id (identity), public_id, lab_id (FK -> labs), booked_by_user_id
///   (FK -> identity_db.user), module_id (nullable FK -> academic_db.module),
///   purpose, start_at, end_at (timestamptz, stored in UTC), status, created_at,
///   booking_type.
///
/// DB rules worth knowing:
///   - status       IN (PENDING, APPROVED, REJECTED, CANCELLED)  - see LabBookingStatus
///   - booking_type IN (OPEN LAB, STUDYTHON, OTHER)              - see LabBookingType
///   - end_at > start_at
///   - ex_lab_bookings_no_overlap: no two APPROVED bookings of the
///     same lab may overlap (Postgres exclusion constraint).
/// </summary>
public class LabBooking
{
    public long booking_id { get; set; }

    public Guid public_id { get; set; }

    public long lab_id { get; set; }

    // identity_db.user.user_id of the lecturer / tutor / mentor who booked.
    public int booked_by_user_id { get; set; }

    // Optional: not every booking is for a specific module.
    public int? module_id { get; set; }

    public string purpose { get; set; } = string.Empty;

    // Stored as UTC (timestamptz).
    public DateTime start_at { get; set; }

    public DateTime end_at { get; set; }

    public string status { get; set; } = LabBookingStatus.Approved;

    public DateTime created_at { get; set; }

    public string booking_type { get; set; } = LabBookingType.Other;

    /// <summary>
    /// The lecturer-only "Has internet" checkbox. Tutor and mentor bookings
    /// always keep the database default (true).
    /// </summary>
    public bool has_internet { get; set; } = true;

    // ---- Approval (docs/booking_approval_2026-11-19.sql) ----

    /// <summary>The System Admin who approved / rejected it. NULL = decided by the system (15:01-07:59) or not yet.</summary>
