public async Task<ApproveBookingResultDto> ApproveBookingAsync(Guid bookingPublicId, int adminUserId, string? note)
{
    var booking = await LoadPendingRequestAsync(bookingPublicId);
    var lab = await _context.Labs.AsNoTracking().FirstOrDefaultAsync(l => l.lab_id == booking.lab_id)
        ?? throw new KeyNotFoundException("That venue no longer exists.");

    if (!lab.is_active)
        throw new InvalidOperationException($"{TitleOf(lab)} is no longer in use, so the booking can't be approved. Reject it or give another venue.");

    var day = await LoadDayDataAsync(DateOnly.FromDateTime(ToLocal(booking.start_at)), excludeBookingId: null);
    var conflict = VenueConflict(lab, day, booking);
    if (conflict != null)
        throw new InvalidOperationException($"{conflict} Reject the request or give another venue.");

    var message = Trim(note);
    var nowUtc = DateTime.UtcNow;

    booking.status = LabBookingStatus.Approved;
    booking.reviewed_by_user_id = adminUserId;
    booking.reviewed_at = nowUtc;
    booking.review_note = message;

    // Everyone else who asked for the same venue at an overlapping time.
    var others = await _context.LabBookings
        .Where(b => b.booking_id != booking.booking_id &&
                    b.lab_id == booking.lab_id &&
                    b.status == LabBookingStatus.Pending &&
                    b.start_at < booking.end_at && b.end_at > booking.start_at)
        .OrderBy(b => b.created_at)
        .ToListAsync();

    foreach (var other in others)
    {
        other.status = LabBookingStatus.Rejected;
        other.reviewed_by_user_id = adminUserId;
        other.reviewed_at = nowUtc;
        other.review_note = OverlapRejectedReason;
    }

    await SaveBookingChangesAsync();

