private async Task<IActionResult> Run<T>(Func<int, Task<T>> action)
{
    var value = User.FindFirst(ClaimTypes.NameIdentifier)?.Value
        ?? User.FindFirst("sub")?.Value
        ?? User.FindFirst("user_id")?.Value;

    if (!int.TryParse(value, out var adminId) || adminId <= 0)
        return Unauthorized(new { message = "Invalid user identity." });

    try
    {
        return Ok(await action(adminId));
    }
    catch (Exception ex) when (LabAccessRequestsController.Map(ex) is { } result)
    {
        return result;
    }
}

