public async Task<LabAccessRequestResponse> ApproveAsync(
    long requestId, int adminUserId, string? message, CancellationToken cancellationToken)
{
    var (entity, admin) = await LoadPendingForAdminAsync(requestId, adminUserId, cancellationToken);
    var note = string.IsNullOrWhiteSpace(message) ? null : message.Trim();

    await EnsureReadModelUserAsync(admin, cancellationToken);
    AddResponse(entity, admin, "APPROVED", note);
    Touch(entity, LabAccessStatus.Approved, admin.user_id);
    await _context.SaveChangesAsync(cancellationToken);

    var view = (await BuildViewsAsync(new List<long> { requestId }, cancellationToken)).Single();

    await LogActivityAsync(adminUserId, "Approved a lab access request", view);

    await NotifyAsync(
        view.LecturerUserId,
        lecturerTitle: $"Lab access request approved – {view.ModuleCode}",
        lecturerMessage:
            $"Your request has been approved. {Who(view, capital: true)} in {view.ModuleCode} " +
            $"now have access to {VenueList(view.Labs)} ({DateRange(view)})." +
            (note != null ? $" Message from the admin: {note}" : string.Empty),
        adminTitle: $"Lab access request approved – {view.ModuleCode}",
        adminMessage:
            $"{FullName(admin)} approved {view.LecturerName}'s request for {view.ModuleCode} " +
            $"to use {VenueList(view.Labs)} ({DateRange(view)}).",
        cancellationToken);

    return view;
}

public async Task<LabAccessRequestResponse> RejectAsync(
    long requestId, int adminUserId, string? message, CancellationToken cancellationToken)
{
    var reason = (message ?? string.Empty).Trim();

    if (reason.Length == 0)
        throw new ArgumentException("Tell the lecturer why the request is rejected.");

    var (entity, admin) = await LoadPendingForAdminAsync(requestId, adminUserId, cancellationToken);

    await EnsureReadModelUserAsync(admin, cancellationToken);
    AddResponse(entity, admin, "REJECTED", reason);
    Touch(entity, LabAccessStatus.Rejected, admin.user_id);
    entity.rejection_reason = reason;
    await _context.SaveChangesAsync(cancellationToken);

    var view = (await BuildViewsAsync(new List<long> { requestId }, cancellationToken)).Single();

    await LogActivityAsync(adminUserId, "Rejected a lab access request", view);

    await NotifyAsync(
        view.LecturerUserId,
        lecturerTitle: $"Lab access request not approved – {view.ModuleCode}",
        lecturerMessage: $"Your request for {view.ModuleCode} to use {VenueList(view.Labs)} was not approved. Reason: {reason}",
        adminTitle: $"Lab access request rejected – {view.ModuleCode}",
        adminMessage: $"{FullName(admin)} rejected {view.LecturerName}'s request for {view.ModuleCode}. Reason: {reason}",
        cancellationToken);

    return view;
}

