public async Task<SpecialBookingSavedDto> CreateAsync(SaveSpecialBookingRequest request, int adminUserId)
{
    var plan = await ValidateAsync(request, isNew: true);

    var clashes = await ClashesAsync(plan.Draft, plan.LabIds, exceptId: null);
    if (clashes.Count > 0)
        throw new InvalidOperationException(string.Join(" ", clashes));

    var row = plan.Draft;
    row.public_id = Guid.NewGuid();
    row.status = SpecialBookingStatus.Active;
    row.created_by_user_id = adminUserId;
    row.created_at = DateTime.UtcNow;
    row.Labs = plan.LabIds.Select(id => new SpecialBookingLab { lab_id = id }).ToList();
    row.Members = await MembersAsync(plan.Emails);

    _context.SpecialBookings.Add(row);
    await _context.SaveChangesAsync();

    var cancelled = await CancelAffectedAsync(row, plan.LabIds, adminUserId);
    var dto = await GetAsync(row.public_id);

    await NotifyMembersAsync(dto, plan.Emails);

    await _activity.LogAsync(adminUserId, VenueActivityCategory.Access, plan.Emails.Count > 0 ? "Uploaded a list" : "Added a special booking",
        $"{dto.Reference} · {string.Join(", ", dto.Venues.Select(v => v.Title))}",
        plan.LabIds.Count == 1 ? plan.LabIds[0] : null,
        Describe(dto, cancelled));

    return Saved(dto, cancelled, "saved");
}

