/// <summary>
/// Writes the System Admin's Venue Activity log (lab_booking_db.venue_activity):
/// venues added / edited / taken out of use, bookings made / moved /
/// cancelled, and lab access requests and decisions.
///
/// Logging never breaks the action being logged: the row is written with
/// its own INSERT (so it does not flush anything else the caller is still
/// tracking), and any failure - e.g. the table not created yet - is only
/// written to the server log.
/// </summary>
public sealed class VenueActivityLogger
{
    private readonly ArmsDbContext _context;
    private readonly ILogger<VenueActivityLogger> _logger;

    public VenueActivityLogger(ArmsDbContext context, ILogger<VenueActivityLogger> logger)
    {
        _context = context;
        _logger = logger;
    }

    /// <param name="actorUserId">Who did it; null for the system.</param>
    /// <param name="category">One of <see cref="VenueActivityCategory"/>.</param>
    /// <param name="action">e.g. "Added a venue".</param>
    /// <param name="target">e.g. "Lab 10-125".</param>
    /// <param name="labId">The venue it concerns, if any (for the venue filter).</param>
    /// <param name="details">Extra lines shown under the entry.</param>
    public async Task LogAsync(
        int? actorUserId,
        string category,
        string action,
        string target,
        long? labId = null,
        IEnumerable<string>? details = null)
    {
        try
        {
            var (name, role, number) = await DescribeActorAsync(actorUserId);
            var lines = (details ?? Enumerable.Empty<string>())
                .Where(d => !string.IsNullOrWhiteSpace(d))
                .Select(d => d.Trim())
                .ToArray();

            await _context.Database.ExecuteSqlInterpolatedAsync($"""
                INSERT INTO lab_booking_db.venue_activity
                    (occurred_at, actor_user_id, actor_name, actor_role, actor_number,
                     category, action, target, lab_id, details)
                VALUES
                    ({DateTime.UtcNow}, {actorUserId}, {Cut(name, 150)}, {Cut(role, 50)}, {Cut(number, 30)},
                     {category}, {Cut(action, 100)}, {Cut(target, 300)}, {labId}, {lines})
                """);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Could not write venue activity '{Action}' for {Target}.", action, target);
        }
    }

