public async Task<int> CreateAsync(
    string type,
    string title,
    string message,
    IEnumerable<int> recipientUserIds,
    int? classTimetableId = null,
    int? testTimetableId = null,
    int? supportId = null,
    int? contactMessageId = null,
    CancellationToken cancellationToken = default)
{
    var recipients = (recipientUserIds ?? Enumerable.Empty<int>())
        .Where(id => id > 0)
        .Distinct()
        .ToList();

    if (recipients.Count == 0)
    {
        return 0;
    }

    var notification = new Notification
    {
        notification_type = NotificationType.Normalize(type),
        title = Trim(title, 150),
        message = string.IsNullOrWhiteSpace(message) ? title : message,
        class_timetable_id = classTimetableId,
        test_timetable_id = testTimetableId,
        support_id = supportId,
        contact_us_message_id = contactMessageId,
        created_at = DateTime.UtcNow,
        recipients = recipients
            .Select(uid => new UserNotification
            {
                user_id = uid,
                is_read = false
            })
            .ToList()
    };

    _context.Notifications.Add(notification);
    await _context.SaveChangesAsync(cancellationToken);

    return recipients.Count;
}

/// <summary>Delivers a notification to every user that holds <paramref name="roleName"/>.</summary>
public async Task<int> NotifyRoleAsync(
    string type,
    string title,
    string message,
    string roleName,
    int? classTimetableId = null,
    int? testTimetableId = null,
    int? supportId = null,
    int? contactMessageId = null,
    CancellationToken cancellationToken = default)
{
    var userIds = await UsersInRoleAsync(roleName, cancellationToken);

    return await CreateAsync(
        type, title, message, userIds,
        classTimetableId, testTimetableId, supportId, contactMessageId,
        cancellationToken);
}

