public async Task<SupportTicketDto> SubmitAsync(
    int submitterUserId,
    SubmitSupportTicketDto request)
{
    var category = ContactMessageCategory.Normalize(request?.Category);

    if (category == null)
    {
        throw new ArgumentException(
            $"category must be one of: {string.Join(", ", ContactMessageCategory.All)}.");
    }

    if (string.IsNullOrWhiteSpace(request!.Subject))
    {
        throw new ArgumentException("subject is required.");
    }

    if (string.IsNullOrWhiteSpace(request.Message))
    {
        throw new ArgumentException("message is required.");
    }

    var submitter = await _context.Users
        .AsNoTracking()
        .FirstOrDefaultAsync(u => u.user_id == submitterUserId);

    if (submitter == null)
    {
        throw new InvalidOperationException("Submitter account could not be found.");
    }

    var entity = new SupportTicket
    {
        user_id = submitterUserId,
        category = category,
        subject = Limit(request.Subject, 200),
        message = request.Message.Trim(),
        admin_feedback = null,
        is_resolved = false,
        created_at = DateTime.UtcNow
    };

    _context.SupportTickets.Add(entity);
    await _context.SaveChangesAsync();

    // Never let an alerting problem fail the submission - the ticket is
    // already saved at this point.
    try
    {
        await AlertSystemAdminsAsync(entity, submitter);
    }
    catch (Exception ex)
    {
        _logger.LogError(
            ex,
            "Failed to alert SystemAdmins about support ticket {Id}.",
            entity.support_id);
    }

    return ToDto(entity, submitter);
}

