public async Task<SupportTicketDto?> RespondAsync(
    int ticketId,
    RespondToSupportTicketDto request)
{
    var ticket = await _context.SupportTickets
        .FirstOrDefaultAsync(t => t.support_id == ticketId);

    if (ticket == null)
    {
        return null;
    }

    if (!string.IsNullOrWhiteSpace(request.AdminFeedback))
    {
        ticket.admin_feedback = request.AdminFeedback.Trim();
    }

    ticket.is_resolved = request.Resolve;

    await _context.SaveChangesAsync();

    var submitter = await _context.Users
        .AsNoTracking()
        .FirstOrDefaultAsync(u => u.user_id == ticket.user_id);

    // As with submission, an alerting failure must not undo the response
    // that was already saved.
    try
    {
        if (submitter != null)
        {
            await AlertSubmitterAsync(ticket, submitter);
        }
    }
    catch (Exception ex)
    {
        _logger.LogError(
            ex,
            "Failed to alert the submitter about support ticket {Id}.",
            ticket.support_id);
    }

    return ToDto(ticket, submitter);
}

