function deriveStats(timetables) {
  const countWithStatus = (status) => timetables.filter((timetable) => timetable.status === status).length
  const weekAgo = Date.now() - WEEK_MS

  return {
    publishedTimetables: countWithStatus('published'),
    pendingTimetables: countWithStatus('pending'),
    inactiveTimetables: countWithStatus('inactive'),
    pendingUploadedThisWeek: timetables.filter(
      (timetable) => timetable.status === 'pending' && uploadedTime(timetable) >= weekAgo,
    ).length,
    recentUploads: [...timetables]
      .sort((a, b) => uploadedTime(b) - uploadedTime(a) || a.name.localeCompare(b.name))
      .slice(0, RECENT_UPLOAD_COUNT),
  }
}

