const handleCreate = async (file) => {
  // The faculty list loads separately from the table (see the hook).
  if (table.faculties.length === 0) {
    toast.error("The faculty list hasn't loaded from the server yet. Try again in a moment.")
    return
  }
  const facultyId = findFacultyId(table.faculties, info.faculty)
  if (facultyId == null) {
    console.error('No backend faculty matches', info.faculty, 'in', table.faculties)
    toast.error(`Timetable upload unsuccessful — "${info.faculty}" isn't set up as a faculty on the server yet.`)
    return
  }
  setUploading(true)
  try {
    const nameWithoutExtension = file.name.replace(/\.[^./]+$/, '')
    const created = await table.uploadTimetable({
      file,
      name: nameWithoutExtension,
      ...info,
      facultyId,
      uploadedBy: user?.name,
    })

    setCreatedTimetable({
      id: created?.id ?? null,
      name: nameWithoutExtension,
      type: info.type,
      year: Number(info.year),
      period: info.period,
      faculty: info.faculty,
    })
    toast.success(
      table.supportsClashCheck(info.type)
        ? 'Timetable uploaded. Checking it for clashes before you publish.'
        : 'Timetable uploaded. Publish it to make it visible.',
    )
  } catch (error) {
    toast.error(error?.message || 'Timetable upload unsuccessful. Please try again.')
  } finally {
    setUploading(false)
  }
}

