const loadTimetables = async () => {
  const data = await fetchManagedTimetables()
  rememberForPage({ timetables: data })
  setTimetables(data)
  return data
}

// The list shows as soon as the timetables arrive; the faculty list (only
// the edit dialog and the upload need it) loads alongside without holding
// the table up — on a cold backend it can take much longer.
useEffect(() => {
  let cancelled = false
  // Only the first visit this session shows the loading state.
  if (readCached().timetables === undefined) setLoading(true)
  loadTimetables().finally(() => {
    if (!cancelled) setLoading(false)
  })
  fetchFaculties().then((facultyList) => {
    if (!cancelled) setFaculties(rememberForPage({ faculties: facultyList }).faculties)
  })
  return () => {
    cancelled = true
  }
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [])

/** Runs (or re-runs) the clash check for one class timetable. */
const recheckClashes = async (id) => {
  if (id == null) return null
  requestedClashIds.current.add(id)
  setClashReports((prev) => ({ ...prev, [id]: { state: 'checking' } }))
  let report
  try {
    report = await fetchTimetableClashes(id)
  } catch (error) {
    report = { state: 'error', error: error?.message }
  }
  setClashReports((prev) => ({ ...prev, [id]: report }))
  return report
}

// Check every class timetable that hasn't been checked yet (a fresh upload
// shows up here as soon as the list is refetched).
useEffect(() => {
  timetables
    .filter((item) => supportsClashCheck(item.type) && !requestedClashIds.current.has(item.id))
    .forEach((item) => recheckClashes(item.id))
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [timetables])

