// Search + type/year/period filters. Every tab lists from this, so each
// tab's count says how many timetables it would show.
const matchingQuery = useMemo(
  () =>
    timetables.filter((item) => matchesSearch(item, search.trim()) && matchesFilters(item, filters, 'status')),
  [timetables, search, filters],
)

const viewCounts = useMemo(() => {
  const counts = { all: matchingQuery.length, pending: 0, published: 0, inactive: 0, clashes: 0 }
  matchingQuery.forEach((item) => {
    if (item.status in counts) counts[item.status] += 1
    if (hasClashes(item)) counts.clashes += 1
  })
  return counts
}, [matchingQuery, clashReports])

// The status tabs list one status (or all of them); "Has clashes" lists
// clashing timetables whatever their status.
const filtered = useMemo(
  () =>
    matchingQuery.filter((item) =>
      clashesOnly
        ? hasClashes(item)
        : filters.status.length === 0 || filters.status.includes(item.status),
    ),
  [matchingQuery, clashesOnly, filters.status, clashReports],
)

/** The open tab: 'all' | 'pending' | 'published' | 'inactive' | 'clashes'. */
const view = clashesOnly ? 'clashes' : (filters.status[0] ?? 'all')

const sorted = useMemo(() => {
  const value = SORT_VALUE[sort.key] ?? SORT_VALUE.uploaded
  const direction = sort.dir === 'asc' ? 1 : -1
  return [...filtered].sort((a, b) => {
    const left = value(a, clashReports)
    const right = value(b, clashReports)
    if (left < right) return -direction
    if (left > right) return direction
    return a.name.localeCompare(b.name)
  })
}, [filtered, sort, clashReports])

const pageCount = Math.max(1, Math.ceil(sorted.length / pageSize))
const currentPage = Math.min(page, pageCount)
const rangeStart = sorted.length === 0 ? 0 : (currentPage - 1) * pageSize + 1
const rangeEnd = Math.min(currentPage * pageSize, sorted.length)
const pageItems = sorted.slice(rangeStart > 0 ? rangeStart - 1 : 0, rangeEnd)

