export const uploadManagedTimetable = async ({ file, name, type, year, period, facultyId }) => {
  const isClass = type === 'Class Timetable'
  const formData = new FormData()
  formData.append('file', file)
  formData.append('name', name)
  formData.append('academicYear', String(Number(year)))
  formData.append('academicPeriod', period)
  formData.append('facultyId', String(Number(facultyId)))

  try {
    // The api instance defaults to application/json, which makes Axios
    // serialize FormData into JSON — override so it's sent as multipart.
    await api.post(
      isClass ? ENDPOINTS.TIMETABLE_MANAGEMENT.UPLOAD_CLASS : ENDPOINTS.TIMETABLE_MANAGEMENT.UPLOAD_TEST,
      formData,
      {
        headers: { 'Content-Type': 'multipart/form-data' },
        params: isClass ? undefined : { testType: TEST_TYPE_BY_TIMETABLE_TYPE[type] ?? 'Semester Test' },
      },
    )
  } catch (error) {
    console.error('Failed to upload timetable', error?.response?.status, error?.response?.data ?? error)
    throw new Error(uploadErrorMessage(error, 'Timetable upload unsuccessful. Please try again.'))
  }
}

ad-tm-hook-upload.code:
const uploadTimetable = async ({ file, name, type, year, period, facultyId, faculty, uploadedBy }) => {
  try {
    await uploadManagedTimetable({ file, name, type, year, period, facultyId })
  } catch (error) {
    // A timed-out upload may still have been created by the server, so
    // refresh the list before reporting the failure.
    await loadTimetables()
    throw error
  }
  const refreshed = await loadTimetables()
  const by = uploadedBy ? `${uploadedBy} uploaded` : 'Uploaded'
  await pushUploadNotification({
    title: 'New timetable uploaded',
    message: `${by} the ${period} ${year} ${type}${faculty ? ` - ${faculty}` : ''} (${name}). It is pending until published.`,
  })

  // The upload response has no id, so pick the record just created out of
  // the refreshed list (newest first): same name/type/faculty/year/period,
  // still Pending. The page uses its id to show the clash check result.
  return (
    refreshed.find(
      (item) =>
        item.status === 'pending' &&
        item.name === name &&
        item.type === type &&
        Number(item.facultyId) === Number(facultyId) &&
        Number(item.year) === Number(year) &&
        item.period === period,
    ) ?? null
  )
}

