export const fetchTimetableClashes = async (id) => {
  // Dev-bypass sessions can't call TIMETABLE_MANAGEMENT.CLASHES (it would
  // 401); the short delay lets the "Checking..." state be seen.
  if (isDevSession()) {
    await new Promise((resolve) => setTimeout(resolve, 600))
    return getDemoTimetableClashes(id)
  }
  try {
    const { data } = await api.get(ENDPOINTS.TIMETABLE_MANAGEMENT.CLASHES(id))
    const clashes = (data?.clashes ?? []).map((clash, index) => ({
      id: `${clash.day}-${clash.time}-${index}`,
      day: clash.day ?? '',
      time: clash.time ?? '',
      studentCount: Number(clash.studentCount ?? clash.students?.length ?? 0),
      students: clash.students ?? [],
      sessions: (clash.sessions ?? []).map((session) => ({
        moduleCode: session.moduleCode ?? '',
        moduleName: session.moduleName ?? '',
        group: session.group ?? '',
        venue: session.venue ?? '',
        time: session.time ?? '',
      })),
    }))

