export default function TimetableClashIndicator({ applicable, report, onOpen, onRetry }) {
  if (!applicable) {
    return (
      <span className="text-muted-foreground" title="Clash checks only apply to class timetables">
        <span aria-hidden="true">—</span>
        <span className="sr-only">Not applicable</span>
      </span>
    )
  }

  if (!report || report.state === 'checking') {
    return (
      <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
        <LoaderCircle className="size-3.5 animate-spin" aria-hidden="true" />
        Checking…
      </span>
    )
  }

  if (report.state === 'error') {
    return (
      <span className="inline-flex flex-wrap items-center gap-x-2 text-xs text-muted-foreground">
        Couldn&apos;t check
        <button type="button" onClick={onRetry} className="font-medium text-primary hover:underline">
          Retry
        </button>
      </span>
    )
  }

  // "None" only when there are no student AND no lecturer clashes.
  if (!hasAnyClashes(report)) {
    return (
      <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
        <CheckCircle2 className="size-3.5 text-green-700 dark:text-green-400" aria-hidden="true" />
        None
      </span>
    )
  }

  const total = totalClashCount(report)
  const studentCount = Number(report.total ?? 0)
  const lecturerCount = Number(report.lecturerTotal ?? 0)
  const breakdown = [
    `${plural(studentCount, 'student clash', 'es')} (${plural(Number(report.studentsWithClashes ?? 0), 'student')} affected)`,
    `${plural(lecturerCount, 'lecturer clash', 'es')} (${plural(Number(report.lecturersWithClashes ?? 0), 'lecturer')} affected)`,
  ].join(', ')

  return (
    <button
      type="button"
      onClick={onOpen}
      title={`${breakdown} — view the clash report`}
      aria-label={`${plural(total, 'clash', 'es')}: ${breakdown}. View the clash report.`}
      className="group inline-flex items-center gap-1.5 whitespace-nowrap rounded-full bg-destructive/10 py-0.5 pl-2 pr-1.5 text-xs font-medium text-destructive transition-colors hover:bg-destructive/15"
    >
      <span aria-hidden="true" className="size-1.5 rounded-full" style={{ background: 'var(--status-clash)' }} />
      {plural(total, 'clash', 'es')}
      <ChevronRight className="size-3.5 transition-transform group-hover:translate-x-0.5" aria-hidden="true" />
    </button>
  )
}

