/** One line for the Publish confirmation, so clashes are seen before publishing. */
const clashSummary = () => {
  if (!clashApplicable || !clashReport) return ''
  if (clashReport.state === 'checking') return ' The clash check is still running.'
  if (!isClashCheckDone(clashReport)) return ' The clash check could not be completed.'
  if (!hasAnyClashes(clashReport)) return ' Clash check: no student or lecturer clashes found.'
  const parts = [
    clashReport.total > 0
      ? `${plural(clashReport.total, 'student clash', 'es')} affecting ${plural(clashReport.studentsWithClashes, 'student')}`
      : null,
    (clashReport.lecturerTotal ?? 0) > 0
      ? `${plural(clashReport.lecturerTotal, 'lecturer clash', 'es')} affecting ${plural(clashReport.lecturersWithClashes ?? 0, 'lecturer')}`
      : null,
  ].filter(Boolean)
  return ` It has ${parts.join(' and ')} — you can still publish it, then send the clash report to the timetable department.`
}

/** Runs one backend action, ignoring repeat clicks while it's in flight. */
const runAction = async (action, successMessage, fallbackError) => {
  if (busy) return false
  setBusy(true)
  try {
    await action()
    toast.success(successMessage)
    return true
  } catch (error) {
    toast.error(error?.message || fallbackError)
    return false
  } finally {
    setBusy(false)
  }
}

