export const buildEventsByDate = (events) => {
  const map = new Map()
  const add = (dateKey, event) => {
    const list = map.get(dateKey) ?? []
    list.push(event)
    map.set(dateKey, list)
  }
  for (const event of events) {
    if (!event.endDate || event.endDate <= event.date) {
      add(event.date, event)
      continue
    }
    const ranged = { ...event, rangeStart: event.date, rangeEnd: event.endDate }
    const [y, m, d] = event.date.split('-').map(Number)
    for (let day = new Date(y, m - 1, d); toDateKey(day) <= event.endDate; day.setDate(day.getDate() + 1)) {
      add(toDateKey(day), ranged)
    }
  }
  return map
}

