function useMonthCellCapacity(gridRef, enabled) {

  const isPhone = useMediaQuery('(max-width: 639px)')

  const [capacity, setCapacity] = useState(2)

  useEffect(() => {

    const grid = gridRef.current

    if (!enabled || !grid) return undefined

    const measure = () => {

      const content =
        grid.querySelector('.calendar-day-cell-content')

      if (!content) return

      const rem =
        parseFloat(
          getComputedStyle(document.documentElement).fontSize
        ) || 16

      const freeRem =
        content.clientHeight / rem - MONTH_CELL_NUMBER_REM

      setCapacity(
        Math.max(0, Math.floor(freeRem / MONTH_CELL_LINE_REM))
      )
    }

    measure()

    const observer = new ResizeObserver(measure)
    observer.observe(grid)

    return () => observer.disconnect()

  }, [gridRef, enabled])

  return isPhone ? 0 : capacity
}

