ad-br-groups.code:
export function groupBookingRequests(requests) {
  const byVenueDay = new Map()
  for (const request of requests) {
    const key = `${request.venueId}|${request.date}`
    if (!byVenueDay.has(key)) byVenueDay.set(key, [])
    byVenueDay.get(key).push(request)
  }

  const groups = []
  for (const list of byVenueDay.values()) {
    const sorted = [...list].sort((a, b) => a.startMinutes - b.startMinutes || a.endMinutes - b.endMinutes)
    let current = null
    for (const request of sorted) {
      // Overlapping times (or a chain of them) are one group.
      if (current && request.startMinutes < current.endMinutes) {
        current.requests.push(request)
        current.endMinutes = Math.max(current.endMinutes, request.endMinutes)
        continue
      }
      current = {
        id: `${request.venueId}|${request.date}|${request.startMinutes}`,
        venueId: request.venueId,
        venueName: request.venueName,
        venueCampus: request.venueCampus,
        venueBuilding: request.venueBuilding,
        venueLocation: request.venueLocation,
        date: request.date,
        startMinutes: request.startMinutes,
        endMinutes: request.endMinutes,
        requests: [request],
      }
      groups.push(current)
    }
  }

  // Oldest request first inside a group (first come is a fair tie-breaker to show).
  groups.forEach((group) => group.requests.sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt))))
  return groups.sort((a, b) => a.date.localeCompare(b.date) || a.startMinutes - b.startMinutes || a.venueName.localeCompare(b.venueName))
}

/** Whether two requests in a group want overlapping times (approving one rejects the other). */
export const requestsOverlap = (a, b) => a.startMinutes < b.endMinutes && b.startMinutes < a.endMinutes

