export const NOTIFICATION_GROUPS = [
  { key: 'today', label: 'Today' },
  { key: 'week', label: 'This Week' },
  { key: 'earlier', label: 'Earlier' },
]

const startOfDay = (date) => new Date(date.getFullYear(), date.getMonth(), date.getDate())

/** Monday 00:00 of the week `date` falls in. */
const startOfWeek = (date) => {
  const day = startOfDay(date)
  day.setDate(day.getDate() - ((day.getDay() + 6) % 7))
  return day
}

/** @returns {'today' | 'week' | 'earlier'} */
export const notificationGroupFor = (value, now = new Date()) => {
  const date = new Date(value)
  if (!value || Number.isNaN(date.getTime())) return 'earlier'
  if (date >= startOfDay(now)) return 'today'
  if (date >= startOfWeek(now)) return 'week'
  return 'earlier'
}

/** @returns {{ key: string, label: string, items: object[] }[]} the non-empty groups, in order. */
export const groupNotificationsByDate = (notifications, now = new Date()) => {
  const byKey = Object.fromEntries(NOTIFICATION_GROUPS.map((group) => [group.key, []]))
  for (const notification of notifications) {
    byKey[notificationGroupFor(notification.date, now)].push(notification)
  }
  return NOTIFICATION_GROUPS.map((group) => ({ ...group, items: byKey[group.key] })).filter(
    (group) => group.items.length > 0,
  )
}

