// An unresolved query turns amber after WAIT_WARNING_DAYS and red after
// WAIT_OVERDUE_DAYS, so ones that have been left stand out in the queue.
export const WAIT_WARNING_DAYS = 3
export const WAIT_OVERDUE_DAYS = 7

/** @returns {'ok'|'warning'|'overdue'} how long an unresolved query has waited (resolved ones are always 'ok'). */
export const ticketWaitLevel = (ticket, now = new Date()) => {
  if (ticket.isResolved) return 'ok'
  const days = daysSince(ticket.createdAt, now)
  if (days > WAIT_OVERDUE_DAYS) return 'overdue'
  if (days > WAIT_WARNING_DAYS) return 'warning'
  return 'ok'
}

export const WAIT_LEVEL_CLASS = {
  ok: 'text-muted-foreground',
  warning: 'font-medium text-amber-700 dark:text-amber-300',
  overdue: 'font-medium text-destructive',
}

