function findNextClass(timetable, now) {
  const currentDay = now.getDay()
  const currentMinutes = now.getHours() * 60 + now.getMinutes()

  let best = null
  for (const entry of timetable) {
    const entryDayIndex = DAY_INDEX[entry.day]
    if (!entryDayIndex) continue
    const [hours, minutes] = entry.startTime.split(':').map(Number)
    const entryMinutes = hours * 60 + minutes
    let dayDiff = (entryDayIndex - currentDay + 7) % 7
    if (dayDiff === 0 && entryMinutes < currentMinutes) dayDiff = 7
    const minutesUntil = dayDiff * 24 * 60 + (entryMinutes - currentMinutes)
    if (!best || minutesUntil < best.minutesUntil) best = { entry, minutesUntil }
  }
  if (!best) return null

  return {
    moduleCode: best.entry.moduleCode,
    moduleName: best.entry.moduleName ?? best.entry.moduleCode,
    groups: best.entry.groups,
    venue: best.entry.venue,
    startsInLabel: formatStartsIn(best.minutesUntil),
  }
}

