function assignClashLanes(entries) {
  const lanesById = new Map()
  const byDay = new Map()

  entries.forEach((entry) => {
    const list = byDay.get(entry.day) ?? []
    list.push({ id: String(entry.id), start: toMinutes(entry.startTime), end: toMinutes(entry.endTime) })
    byDay.set(entry.day, list)
  })

  byDay.forEach((dayEntries) => {
    dayEntries.sort((a, b) => a.start - b.start || a.end - b.end)

    let group = []
    let laneEnds = []
    let groupEnd = -Infinity

    const closeGroup = () => {
      if (laneEnds.length > 1) {
        group.forEach(({ id, lane }) => lanesById.set(id, { lane, lanes: laneEnds.length }))
      }
      group = []
      laneEnds = []
    }

    dayEntries.forEach((item) => {
      // Back-to-back classes (one ends as the next starts) don't clash.
      if (item.start >= groupEnd) {
        closeGroup()
        groupEnd = item.end
      } else {
        groupEnd = Math.max(groupEnd, item.end)
      }

      // First lane that is free by the time this class starts.
      let lane = laneEnds.findIndex((laneEnd) => laneEnd <= item.start)
      if (lane === -1) {
        lane = laneEnds.length
        laneEnds.push(item.end)
      } else {
        laneEnds[lane] = item.end
      }

      group.push({ id: item.id, lane })
    })

    closeGroup()
  })

  return lanesById
}

