export function useLecturerGroups(lecturerId) {
  // Already loaded this session: shown at once, refreshed in the background.
  const cacheKey = pageCacheKey('lecturer-groups', lecturerId)
  const [allGroups, setAllGroups] = useState(() => readPageCache(cacheKey) ?? [])
  const [loading, setLoading] = useState(() => readPageCache(cacheKey) === undefined)
  const [search, setSearch] = useState('')

  useEffect(() => {
    let cancelled = false
    ;(async () => {
      const cached = readPageCache(cacheKey)
      if (cached === undefined) {
        setLoading(true)
      } else {
        setAllGroups(cached)
        setLoading(false)
      }
      const data = await fetchLecturerGroups(lecturerId)
      if (!cancelled) {
        setAllGroups(writePageCache(cacheKey, data))
        setLoading(false)
      }
    })()
    return () => {
      cancelled = true
    }
  }, [lecturerId, cacheKey])

  const groups = useMemo(() => {
    const query = search.trim().toLowerCase()
    if (!query) return allGroups
    return allGroups.filter(
      (group) =>
        group.moduleName.toLowerCase().includes(query) || group.moduleCode.toLowerCase().includes(query),
    )
  }, [allGroups, search])

  const totalStudents = useMemo(
    () => allGroups.reduce((total, group) => total + (group.studentCount ?? 0), 0),
    [allGroups],
  )

  return { groups, loading, search, setSearch, totalModules: allGroups.length, totalStudents }
}

