export const fetchLecturerGroups = async (lecturerId) => {
  const timetable = await fetchTimetable({ role: 'lecturer', lecturerId })

  const moduleMap = new Map()
  for (const entry of timetable) {
    if (!moduleMap.has(entry.moduleCode)) {
      moduleMap.set(entry.moduleCode, {
        id: entry.moduleCode,
        moduleCode: entry.moduleCode,
        moduleName: entry.moduleName ?? entry.moduleCode,
        groups: new Set(),
        groupIds: new Set(),
        sessions: new Map(),
      })
    }
    const module = moduleMap.get(entry.moduleCode)
    entry.groups.forEach((group) => module.groups.add(group))
    // A merged session carries every group it covers in groupIds.
    const entryGroupIds = entry.groupIds?.length ? entry.groupIds : [entry.groupId]
    entryGroupIds.forEach((id) => {
      if (id != null) module.groupIds.add(id)
    })
    if (entry.day && entry.startTime && entry.endTime) {
      // Keep day, time and venue together as one row so a module that meets
      // at different times/venues on different days stays unambiguous.
      const session = {
        day: entry.day,
        dayLabel: DAY_LABELS[entry.day] ?? entry.day,
        time: `${entry.startTime.slice(0, 5)} - ${entry.endTime.slice(0, 5)}`,
        venue: entry.venue ?? '',
      }

