/**
 * Click a free period to select it; click it again to unselect it. A second period has to sit
 * right next to the selection (same day, back to back). Clicking one that doesn't starts a
 * new selection with it, and a toast says why.
 */
const chooseSlot = (slotDate, slot) => {
  setMessage('')
  setFieldErrors((current) => ({ ...current, selection: undefined }))
  if (!isSelectable(slot)) return
  const only = (entry) => ({ date: slotDate, start: entry.start, end: entry.end })
  const goToDay = () => {
    if (slotDate !== date) onDateChange(slotDate)
  }

  if (!selection) {
    setSelection(only(slot))
    return goToDay()
  }

  const chosen = selection.date === slotDate ? slotsOf(slotDate).filter((entry) => entry.start >= selection.start && entry.end <= selection.end) : []
  const isChosen = chosen.some((entry) => entry.key === slot.key)

  if (isChosen) {
    const rest = chosen.filter((entry) => entry.key !== slot.key)
    // Unselecting one end keeps the other period(s) selected.
    return setSelection(rest.length ? { date: slotDate, start: rest[0].start, end: rest[rest.length - 1].end } : null)
  }

  // Working hours (needs approval) and after hours (confirmed automatically) are booked separately.
  if (chosen.length && isAfter(chosen[0]) !== isAfter(slot)) {
    toast.error('Book working hours and after hours separately', {
      description: 'A booking is either timetable periods or after-hours slots, so your earlier selection was cleared.',
    })

