const submit = async (event) => {
  event.preventDefault()
  setSubmitted(true)
  setMessage('')
  const nextErrors = validateForm()
  if (Object.keys(nextErrors).length) {
    setFieldErrors(nextErrors)
    setMessage('Please correct the highlighted fields before submitting your booking.')
    focusFirstInvalidField(nextErrors)
    return
  }

  setFieldErrors({})
  const slotsChosen = { venueId, date: selection.date, start: selection.start, end: selection.end }
  try {
    if (rescheduling) {
      const moved = await reschedule(rescheduling.id, slotsChosen)
      toast.success(moved.approval === 'pending' ? 'Request sent for the new time' : 'Booking moved', {
        description: `${moved.venueName}, ${formatDayShort(moved.date)}, ${moved.timeRange}${moved.approval === 'pending' ? ' · waiting for approval' : ''}`,
      })
      onRescheduled(moved)
    } else {
      const created = await book({
        ...slotsChosen,
        purpose: bookingPurpose(),
        isOpenLab: purpose === OPEN_LAB_PURPOSE,
        ...(showInternetOption ? { hasInternet } : {}),
      })
      setBooked(created)
      setSelection(null)
      setPurpose('')
      setPurposeDescription('')
      setHasInternet(true)
      setSubmitted(false)
    }
  } catch (bookingError) {
    setMessage(bookingError.message)
    refreshAll()
  }
}

