const escapeRegExp = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

/** @returns {string[]} the lower-cased words of a search string. */
export const searchWords = (text) => String(text ?? '').toLowerCase().split(/\s+/).filter(Boolean)

export default function Highlight({ text, words }) {
  if (!words?.length) return text
  const pattern = new RegExp(`(${words.map(escapeRegExp).join('|')})`, 'gi')
  return String(text)
    .split(pattern)
    .map((part, index) =>
      // split() with a capture group puts the matches at the odd indexes.
      index % 2 === 1 ? (
        <mark key={index} className="rounded-sm bg-warning/35 px-0.5 text-inherit">
          {part}
        </mark>
      ) : (
        part
      ),
    )
}

