export const NOTIFICATION_PREFERENCE_OPTIONS = [
  { key: 'academic', label: 'Academic' },
  { key: 'administrative', label: 'Administrative' },
  { key: 'calendar', label: 'Calendar Events' },
  // Venue prototype.
  { key: 'venues', label: 'Academic Venues' },
]

export function useNotificationPreferences(userId, options = NOTIFICATION_PREFERENCE_OPTIONS) {
  const [preferences, setPreferences] = useState({})
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    let cancelled = false
    ;(async () => {
      setLoading(true)
      const data = await fetchNotificationPreferences(userId)
      if (!cancelled) {
        setPreferences(data)
        setLoading(false)
      }
    })()
    return () => {
      cancelled = true
    }
  }, [userId])

  const toggle = async (key) => {
    const next = { ...preferences, [key]: !preferences[key] }
    setPreferences(next)
    setError(null)
    try {
      await updateNotificationPreferences(userId, next)
    } catch (err) {
      setError(err)
    }
  }

  return { preferences, loading, error, toggle, options }
}

