st-template.code:
const rowOf = (minutes) => Math.floor((minutes - TEMPLATE_START) / TEMPLATE_STEP)

/** A day's classes grouped into blocks of overlapping classes, each with its first row and row count. */
function blocksOf(entries) {
  const sorted = entries
    .map((entry) => ({ entry, from: Math.max(clockToMinutes(entry.startTime), TEMPLATE_START), to: Math.min(clockToMinutes(entry.endTime), TEMPLATE_END) }))
    .filter((item) => item.to > item.from)
    .sort((a, b) => a.from - b.from || a.to - b.to)
  const blocks = []
  sorted.forEach((item) => {
    const last = blocks[blocks.length - 1]
    if (last && item.from < last.to) {
      last.items.push(item)
      last.to = Math.max(last.to, item.to)
    } else {
      blocks.push({ from: item.from, to: item.to, items: [item] })
    }
  })
  return blocks.map((block) => {
    const first = rowOf(block.from)
    const last = Math.ceil((block.to - TEMPLATE_START) / TEMPLATE_STEP)
    return { ...block, first, span: Math.max(1, last - first) }
  })
}

