export const fetchSemesterTests = async (studentId) => {
  void studentId
  // Same dev-bypass fallback as timetableService.fetchTimetable — see its
  // comment for why. semesterTestOne/Two is the same stub data this
  // endpoint replaced, kept around for exactly this.
  if (isDevSession()) return { testOne: semesterTestOne, testTwo: semesterTestTwo }
  try {
    const { data } = await api.get(ENDPOINTS.TIMETABLE.STUDENT_TEST)
    // The endpoint returns exams too (test_type "Exam", shown on the
    // Examinations page via fetchExaminations) - semester tests only here.
    const sessions = (data?.timetable ?? []).filter(
      (session) => String(session.test_type ?? '').trim().toLowerCase() !== 'exam',
    )

    const [modulesById, lecturersByUserId] = await Promise.all([
      fetchModulesByIds(sessions.map((session) => session.module_id)),
      fetchLecturersByUserIds(sessions.map((session) => session.lecturer_user_id)),
    ])

    const testOne = sessions.map((session) => ({
      id: session.test_timetable_id,
      date: formatTestDate(session.test_date, session.day_of_week),
      time: formatTimeRange(session.start_time, session.end_time),
      moduleCode: modulesById.get(session.module_id)?.code ?? `Module ${session.module_id}`,
      session: session.session,
      sessionType: session.session_type,
      lecturer: formatLecturerName(lecturersByUserId.get(session.lecturer_user_id)),
      venue: session.venue,
    }))

    return { testOne, testTwo: [] }
  } catch (error) {
    console.error('Failed to load semester tests', error)
    return { testOne: [], testTwo: [] }
  }
}

