export function toVenueUser(armsUser) {
  if (!armsUser) return null
  const account = VENUE_ACCOUNTS_BY_EMAIL[armsUser.email]
  if (account && !hasBackendFlags(armsUser)) return { ...account }

  const role = normalizeRoleKey(armsUser.role)
  const isLecturer = role === 'lecturer'
  const isAdmin = role === 'system-admin'
  return {
    id: `arms-${armsUser.email ?? armsUser.id}`,
    email: armsUser.email ?? '',
    name: armsUser.name ?? armsUser.email ?? 'ARMS user',
    role: isAdmin ? 'admin' : 'booker',
    bookerTypes: isAdmin ? [] : isLecturer ? ['lecturer'] : studentBookerTypes(armsUser),
    number: armsUser.staff_number ?? armsUser.student_number ?? '',
    numberLabel: isLecturer || isAdmin ? 'Staff number' : 'Student number',
    campus: DEFAULT_CAMPUS,
  }
}

const capitalize = (value) => value.charAt(0).toUpperCase() + value.slice(1)

/**
