/** For URLs that match no route (e.g. a typo), which would otherwise render a blank page. */
export function UnknownRouteRedirect() {
  const user = getAuthenticatedUser()
  return <Navigate to={(user && getDashboardRouteForRole(user.role)) ?? ROUTES.LOGIN} replace />
}

export default function ProtectedRoute({ role }) {
  const user = getAuthenticatedUser()
  if (!user) return <Navigate to={ROUTES.LOGIN} replace />

  const userRole = normalizeRoleKey(user.role)
  const allowedRoles = Array.isArray(role) ? role : [role]
  if (!allowedRoles.includes(userRole)) {
    return <Navigate to={getDashboardRouteForRole(userRole) ?? ROUTES.LOGIN} replace />
  }

  return (
    <>
      <Outlet />
      <IdleLogout />
    </>
  )
}

fe-role-routes.code:
export const ROLE_DASHBOARD_ROUTES = {
  student: ROUTES.STUDENT_DASHBOARD,
  lecturer: ROUTES.LECTURER_DASHBOARD,
  'system-admin': ROUTES.SYSTEM_ADMIN_DASHBOARD,
}

// Alternate spellings the backend's role name might come back as (confirmed
// so far: "Student"; lecturer/system-admin unconfirmed) — keyed by the role
// with everything but letters stripped, so casing/spaces/underscores/hyphens
// all normalize the same way.
const ROLE_KEY_ALIASES = {
  student: 'student',
  lecturer: 'lecturer',
  systemadmin: 'system-admin',
  systemadministrator: 'system-admin',
  sysadmin: 'system-admin',
  admin: 'system-admin',
  administrator: 'system-admin',
  timetableadmin: 'system-admin',
}

/**
 * Normalizes a backend role name (any casing/spacing, e.g. "Student",
 * "System Admin", "SystemAdmin") to the canonical key used throughout the
 * app (ROLE_DASHBOARD_ROUTES, NOTIFICATIONS_BY_ROLE, etc: 'student',
 * 'lecturer', 'system-admin'). Returns the lowercased input unchanged if it
 * isn't a recognized alias, and '' for a missing role.
 */
export function normalizeRoleKey(role) {
  const key = String(role ?? '')
    .toLowerCase()
    .replace(/[^a-z]/g, '')
  return ROLE_KEY_ALIASES[key] ?? key
}

/** Resolves a backend role name (any casing/spacing) to its dashboard route, or undefined. */
export function getDashboardRouteForRole(role) {
  return ROLE_DASHBOARD_ROUTES[normalizeRoleKey(role)]
}

fe-auth-guard.code:
/** True for a well-formed JWT whose `exp` is still in the future. */
const isUnexpiredJwt = (token) => {
  try {
    const payload = token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/')
    const { exp } = JSON.parse(atob(payload))
    return typeof exp === 'number' && exp * 1000 > Date.now()
  } catch {
    return false
  }
}

/**
 * The signed-in user for ProtectedRoute, or null when this tab has no usable
 * session (nothing stored, damaged data, an expired or non-JWT token). A
 * session that fails the check is cleared so it can't be picked up again.
 * The dev-bypass token isn't a JWT, so it's exempt (local development only).
 *
 * @returns {object | null}
 */
export const getAuthenticatedUser = () => {
  const token = getSessionItem(TOKEN_KEY)
  let user = null
  try {
    user = getStoredUser()
  } catch {
    // Damaged user data - treated as signed out below.
  }

  if (token && user?.role && (isDevSession() || isUnexpiredJwt(token))) return user

  if (token) removeSessionItem(TOKEN_KEY)
  removeSessionItem(USER_KEY)
  return null
}

