export const authInitialState = {
  user: null,
  token: null,
  isAuthenticated: false,
  // Email awaiting OTP verification (set after login sends the code, read
  // by OtpPage). Restored from sessionStorage so it survives a refresh.
  pendingEmail: readPendingEmail(),
}

export const authReducer = (state, action) => {
  if (action.type === 'auth/setUser') {
    return { ...state, user: action.payload, isAuthenticated: Boolean(action.payload) }
  }
  if (action.type === 'auth/setToken') {
    return { ...state, token: action.payload }
  }
  if (action.type === 'auth/setPendingEmail') {
    writePendingEmail(action.payload)
    return { ...state, pendingEmail: action.payload }
  }
  if (action.type === 'auth/clear') {
    writePendingEmail(null)
    return { ...authInitialState, pendingEmail: null }
  }
  return state
}

