const API_BASE_URL = import.meta.env.VITE_API_BASE_URL ?? 'https://arms-backend-t2p1.onrender.com/api'

// Sign-in endpoints return 401 for *expected* reasons (bad password, bad
// OTP) that LoginPage/OtpPage already surface inline — only a 401 from an
// authenticated request (an expired/invalid token) should force a redirect.
const AUTH_ENDPOINTS = [ENDPOINTS.AUTH.LOGIN, ENDPOINTS.AUTH.VERIFY_OTP]

export const api = axios.create({
  baseURL: API_BASE_URL,
  // Render's free tier spins the backend down when idle; waking it back up
  // can take 20-50s, well past a typical API timeout, so this is generous
