})

fe-api-interceptors.code:
api.interceptors.request.use(
  (config) => {
    // Must match authService.js's TOKEN_KEY.
    const token = getSessionItem('arms_token')
    if (token) {
      config.headers.Authorization = `Bearer ${token}`
    }
    return config
  },
  (error) => Promise.reject(error),
)

api.interceptors.response.use(
  (response) => response,
  (error) => {
    const isAuthEndpoint = AUTH_ENDPOINTS.some((path) => error.config?.url?.includes(path))
    if (error.response?.status === 401 && !isAuthEndpoint && !isDevSession()) {
      removeSessionItem('arms_token')
      removeSessionItem('arms_user')
      if (window.location.pathname !== ROUTES.LOGIN) {
        window.location.assign(ROUTES.LOGIN)
      }
    }
    return Promise.reject(error)
  },
)

