fe-query-load.code:
const STALE_MS = 30_000
const cache = new Map() // keyString -> { data, error, at, promise }
const listeners = new Set() // (keyString) => void, notified when a key is invalidated

const toKey = (key) => JSON.stringify(key)

function startsWith(keyString, prefix) {
  const key = JSON.parse(keyString)
  return prefix.every((part, index) => key[index] === part)
}

function load(keyString, fetcher) {
  const entry = cache.get(keyString)
  if (entry?.promise) return entry.promise
  const promise = Promise.resolve()
    .then(fetcher)
    .then(
      (data) => {
        cache.set(keyString, { data, error: null, at: Date.now(), promise: null })
        return data
      },
      (error) => {
        cache.set(keyString, { data: entry?.data, error, at: 0, promise: null })
        throw error
      },
    )
  cache.set(keyString, { ...(entry ?? {}), promise })
  return promise
}

fe-query-hook.code:
export function useQuery(key, fetcher, { refetchInterval } = {}) {
  const keyString = key ? toKey(key) : null
  const fetcherRef = useRef(fetcher)
  fetcherRef.current = fetcher

  const cached = keyString ? cache.get(keyString) : undefined
  const [state, setState] = useState(() => ({
    data: cached?.data,
    error: cached?.error ?? null,
    loading: cached?.data === undefined,
  }))

  const run = useCallback(
    (force = false) => {
      if (!keyString) return Promise.resolve(undefined)
      const entry = cache.get(keyString)
      const fresh = entry && entry.at && Date.now() - entry.at < STALE_MS
      if (fresh && !force) {
        setState({ data: entry.data, error: null, loading: false })
        return Promise.resolve(entry.data)
      }
      if (force && entry) cache.set(keyString, { ...entry, at: 0 })
      setState((previous) => ({ ...previous, loading: previous.data === undefined }))
      return load(keyString, () => fetcherRef.current()).then(
        (data) => {
          setState({ data, error: null, loading: false })
          return data
        },
        (error) => {
          setState((previous) => ({ ...previous, error, loading: false }))
          return undefined
        },
      )
    },
    [keyString],
  )

  // Load on mount and whenever the key changes.
  useEffect(() => {
    if (!keyString) {
      setState({ data: undefined, error: null, loading: false })
      return undefined
    }
    const entry = cache.get(keyString)
    setState({ data: entry?.data, error: null, loading: entry?.data === undefined })
    run()
    return undefined
  }, [keyString, run])

