fe-page-cache.code:
const ensureOwner = () => {
  const token = getSessionItem(TOKEN_KEY)
  if (token !== cacheOwner) {
    cache.clear()
    cacheOwner = token
  }
  return token
}

/** Builds a cache key from a page/hook name and the values its data depends on. */
export const pageCacheKey = (...parts) => JSON.stringify(parts)

/** @returns {any} the cached value, or undefined when the page has not loaded it yet this session */
export const readPageCache = (key) => {
  if (!ensureOwner()) return undefined
  return cache.get(key)
}

/** Remembers `value` for `key` (only while signed in). Returns `value`. */
export const writePageCache = (key, value) => {
  if (ensureOwner()) cache.set(key, value)
  return value
}

fe-page-cache-use.code:
export function useSemesterTests(userId) {
  // Already loaded this session: shown at once, refreshed in the background.
  const cacheKey = pageCacheKey('semester-tests', userId)
  const [testOne, setTestOne] = useState(() => readPageCache(cacheKey)?.testOne ?? [])
  const [testTwo, setTestTwo] = useState(() => readPageCache(cacheKey)?.testTwo ?? [])
  const [loading, setLoading] = useState(() => readPageCache(cacheKey) === undefined)

  useEffect(() => {
    let cancelled = false
    ;(async () => {
      const cached = readPageCache(cacheKey)
      if (cached === undefined) {
        setLoading(true)
      } else {
        setTestOne(cached.testOne)
        setTestTwo(cached.testTwo)
        setLoading(false)
      }
      const { testOne: one, testTwo: two } = await fetchSemesterTests(userId)
      if (cancelled) return
      writePageCache(cacheKey, { testOne: one, testTwo: two })
      setTestOne(one)
      setTestTwo(two)
      setLoading(false)
    })()
    return () => {
      cancelled = true
    }
  }, [userId, cacheKey])

  return { testOne, testTwo, loading }
}

