const EXPORTER_LOADERS = {
  PDF: () => import('./pdfExport').then((m) => m.exportTableToPdf),
  XLSX: () => import('./excelExport').then((m) => m.exportTableToExcel),
  DOCX: () => import('./wordExport').then((m) => m.exportTableToWord),
}

/**
 * Builds and downloads a `{ title, columns, rows, fileName }` table in the
 * given format. Loads only the exporter library the chosen format needs.
 * @param {'PDF' | 'XLSX' | 'DOCX'} format
 * @param {{ title: string, subtitle?: string, columns: string[], rows: (string|number)[][], fileName: string, orientation?: 'portrait' | 'landscape' }} table
 * @returns {Promise<void>}
 */
export async function exportTable(format, table) {
  const loadExporter = EXPORTER_LOADERS[format]
  if (!loadExporter) throw new Error(`Unsupported export format: ${format}`)
  const exporter = await loadExporter()
  return exporter(table)
}

