export const downloadFile = async (endpoint, { params, fallbackName, errorMessage = 'Unable to download the file.' }) => {
  let response
  try {
    response = await api.get(endpoint, { params, responseType: 'blob' })
  } catch (error) {
    throw new Error(await readErrorMessage(error, errorMessage))
  }

  const fileName = fileNameFromHeader(response.headers?.['content-disposition']) || fallbackName
  const url = URL.createObjectURL(response.data)
  const link = document.createElement('a')
  link.href = url
  link.download = fileName
  document.body.appendChild(link)
  link.click()
  link.remove()
  // Give the browser a moment to start the download before revoking.
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}

