const handleOtpChange = (index, value) => {

    const digit = String(value ?? '').replace(/[^A-Za-z0-9]/g, '').slice(-1)


    // Prevent the user from skipping empty OTP boxes.
    if (index > firstEditableIndex()) {

        inputRefs.current[firstEditableIndex()]?.focus()

        return
    }


    const updatedOtp = [...otp]

    // Only keep one character.
    updatedOtp[index] = digit

    setOtp(updatedOtp)

    // Remove any previous error when the user starts editing.
    setError(null)

    // Typed codes are not auto-submitted: the user presses Verify OTP (or Enter)
    // themselves. Only a pasted code verifies automatically (handleOtpPaste).


    // Automatically move to the next OTP box.
    if (digit && index < otp.length - 1) {

        skipFocusGuard.current = true

        inputRefs.current[index + 1]?.focus()
    }
}

fe-otp-paste.code:
const handleOtpPaste = (index, event) => {

    const pastedValue = event.clipboardData.getData('text')

    if (!pastedValue) return

    const sanitizedValue = String(pastedValue).replace(/[^A-Za-z0-9]/g, '')

    if (!sanitizedValue) return

    event.preventDefault()

    const nextOtp = [...otp]

    for (let otpIndex = index; otpIndex < OTP_LENGTH; otpIndex += 1) {
        nextOtp[otpIndex] = ''
    }

    for (let offset = 0; offset < sanitizedValue.length; offset += 1) {
        const targetIndex = index + offset

        if (targetIndex >= OTP_LENGTH) break

        nextOtp[targetIndex] = sanitizedValue[offset]
    }

    setOtp(nextOtp)
    setError(null)

    // A pasted complete code verifies straight away.
    if (nextOtp.every((entry) => entry !== '')) {
        triggerVerifyIfComplete(nextOtp)
    }

    const nextFocusIndex = Math.min(index + sanitizedValue.length, OTP_LENGTH - 1)

    requestAnimationFrame(() => {
        inputRefs.current[nextFocusIndex]?.focus()
    })
}

