const handleVerifyOtp = async (providedOtp = otp) => {

    const otpArray = Array.isArray(providedOtp)
        ? providedOtp
        : Array.from(String(providedOtp ?? ''))

    const enteredOtp = otpArray
        .map((digit) => String(digit ?? '').replace(/[^A-Za-z0-9]/g, '').slice(-1))
        .join('')

    if (isVerifying) return

    // All six digits must be entered.
    if (enteredOtp.length !== 6) {

        setError('Enter all 6 digits.')

        return
    }


    if (!pendingEmail) {

        setError('Your sign-in session expired. Please sign in again.')

        return
    }


    // Show the circular loading state.
    setIsVerifying(true)

    setError(null)


    try {

        // Verify the entered OTP and get back the real session.
        const { token, user } = await verifyOtp({
            email: pendingEmail,
            otp: enteredOtp,
        })

        dispatch({ type: 'auth/setUser', payload: user })
        dispatch({ type: 'auth/setToken', payload: token })
        dispatch({ type: 'auth/setPendingEmail', payload: null })


        // Find the dashboard belonging to the user's role (student,
        // lecturer, or system-admin).
        const dashboardRoute = getDashboardRouteForRole(user?.role)


        // Go directly to the correct dashboard.
        if (dashboardRoute) {

