export const verifyOtp = async ({ email, otp } = {}) => {
  try {
    const { data } = await api.post(ENDPOINTS.AUTH.VERIFY_OTP, { email, otp })
    // Confirmed shape: { message, token, user: { full_name, surname,
    // displayName, role: "Student", ... } }. Layout/header components read
    // user.name (matching the old demo shape) and expect "S Mokoena" style
    // (first-name initial + surname), so derive it here once rather than
    // touching every consumer. Same for role: components (DashboardLayout's
    // NOTIFICATIONS_BY_ROLE, roleLabel checks, etc.) expect the old demo
    // convention ('student'/'lecturer'/'system-admin'), not the backend's
    // capitalized "Student"/"Lecturer"/... — normalize once here so every
    // consumer's existing lookup just works.
    const token = data?.token ?? null
    const rawUser = data?.user ?? null
    const initialAndSurname =
      rawUser?.full_name && rawUser?.surname ? `${rawUser.full_name.charAt(0)} ${rawUser.surname}` : null
    let user = rawUser
      ? {
          ...rawUser,
          name: initialAndSurname ?? rawUser.displayName ?? rawUser.name,
          role: normalizeRoleKey(rawUser.role),
        }
      : null
    if (token) setSessionItem(TOKEN_KEY, token)
    // A real sign-in always overrides any leftover dev-bypass session flag.
    removeSessionItem(DEV_SESSION_KEY)

    if (user) {
      const faculty = await getMyFaculty()
      if (faculty?.name) user = { ...user, faculty: faculty.name }
      // Which department's picture the dashboard welcome card shows.
      // Falls back to the backend's department when no course name matches
      // (e.g. "Diploma in Multimedia Computing" is Computer Science) or the
      // timetable is empty.
      const department = (await getMyDepartment(user.role, faculty)) ?? faculty?.ownDepartment?.name ?? null
      if (department) user = { ...user, department }
      setSessionItem(USER_KEY, JSON.stringify(user))
    }

    return { token, user }

