const handleResendOtp = async () => {

    if (!pendingEmail) {

        setError('Your sign-in session expired. Please sign in again.')

        return
    }


    setIsResending(true)

    setError(null)

    setNotice(null)


    try {

        const { expiresInMinutes } = await resendOtp({ email: pendingEmail })

        setOtp(Array(OTP_LENGTH).fill(''))

        wipeOnFocus.current = false

        setTimeLeft((expiresInMinutes || 5) * 60)

        setResendCooldown(RESEND_COOLDOWN_SECONDS)

        setNotice(`A new code has been sent to ${pendingEmail}.`)

        inputRefs.current[0]?.focus()

    } catch (err) {

        setError(err?.message || 'Unable to resend the code. Please try again.')

    } finally {

        setIsResending(false)
    }
}

