const isPlainStudent = isStudent && user && !toVenueUser(user)?.bookerTypes?.some((type) => type !== 'student')
const shownNavItems = isPlainStudent
  ? navItems.map((item) => (item.path === ROUTES.STUDENT_MY_BOOKINGS ? { ...item, label: 'Open Lab/Class' } : item))
  : navItems
const shownRoleLabel = isStudent && user ? studentRoleLabel(user) : roleLabel

// Group the flat nav list into categories (first-appearance order).
const sections = []
for (const item of shownNavItems) {
  let group = sections.find((g) => g.label === item.section)
  if (!group) {
    group = { label: item.section, items: [] }
    sections.push(group)
  }
  group.items.push({
    label: item.label,
    href: item.path,
    icon: item.icon ?? undefined,
    count: item.countKey ? navCounts[item.countKey] : 0,
  })
}

