fe-theme-context.code:
export function ThemeProvider({ children }) {
  const location = useLocation()
  const scope = getThemeScope(location.pathname)

  return (
    <ThemeState key={scope} scope={scope}>
      {children}
    </ThemeState>
  )
}

function ThemeState({ children, scope }) {
  const [theme, setTheme] = useState(() => getStoredTheme(scope))

  useEffect(() => {
    applyTheme(theme)
    storeTheme(theme, scope)
  }, [scope, theme])

  useEffect(() => {
    if (theme !== 'system' || typeof window === 'undefined' || !window.matchMedia) return undefined

    const media = window.matchMedia('(prefers-color-scheme: dark)')
    const handleChange = () => applyTheme('system')
    media.addEventListener('change', handleChange)
    return () => media.removeEventListener('change', handleChange)
  }, [theme])

  return <ThemeContext.Provider value={{ theme, setTheme }}>{children}</ThemeContext.Provider>
}

export function useTheme() {
  const context = useContext(ThemeContext)
  if (!context) throw new Error('useTheme must be used within a ThemeProvider')
  return context
}

