const ROLE_THEME_SCOPES = [
  ['student', 'student'],
  ['lecturer', 'lecturer'],
  ['system-admin', 'system-admin'],
]

export function getThemeScope(pathname = '') {
  const roleScope = ROLE_THEME_SCOPES.find(([pathSegment]) => pathname.includes(`/${pathSegment}`))
  return roleScope?.[1] || 'public'
}

export function getThemeStorageKey(scope = 'public') {
  return scope === 'public' ? THEME_STORAGE_KEY : `${THEME_STORAGE_KEY}_${scope}`
}

