// Arrow keys move between tiles and select, like native radio buttons.
const onKeyDown = (event, index) => {
  const step = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[event.key]
  if (!step) return
  event.preventDefault()
  const next = (index + step + APPEARANCE_THEME_OPTIONS.length) % APPEARANCE_THEME_OPTIONS.length
  changeTheme(APPEARANCE_THEME_OPTIONS[next].value)
  tileRefs.current[next]?.focus()
