ux-split-flap.code:
export default function SplitFlapText({
  text = 'COMING SOON',
  className = '',
  startDelay = 80,
  interval = 120,
}) {
  const [shouldAnimate, setShouldAnimate] = useState(false)

  useEffect(() => {
    if (typeof window === 'undefined') {
      setShouldAnimate(true)
      return undefined
    }

    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)')

    if (mediaQuery.matches) {
      setShouldAnimate(true)
      return undefined
    }

    const timeoutId = window.setTimeout(() => {
      setShouldAnimate(true)
    }, startDelay)

    return () => window.clearTimeout(timeoutId)
  }, [startDelay])

  const letters = useMemo(() => Array.from(text), [text])

  return (
    <div className={`split-flap-text ${className}`.trim()} role="text" aria-label={text}>
      {letters.map((character, index) => {
        const isSpace = character === ' '

        return (
          <span
            key={`${character}-${index}`}
            className={[
              'split-flap-letter',
              shouldAnimate ? 'is-animated' : '',
              isSpace ? 'split-flap-letter--space' : '',
            ]
              .filter(Boolean)
              .join(' ')}
            style={{
              '--flip-delay': `${index * interval}ms`,
            }}
          >
            {isSpace ? '\u00A0' : character}
          </span>
        )
      })}
    </div>
  )
}

